INSERT INTO escalations (session_id, channel, type, urgency, phone, summary)
VALUES ($1, $2, 'emergency', 'high', NULLIF(RIGHT(REGEXP_REPLACE($3, '[^0-9]', '', 'g'), 10), ''), $4)
RETURNING id;

SELECT 'departments' AS topic, STRING_AGG(DISTINCT department, ', ') AS content FROM doctors WHERE is_active
UNION ALL
SELECT topic, content FROM hospital_info;

INSERT INTO escalations (session_id, channel, type, urgency, patient_name, phone, summary)
VALUES ($1, $2, $3, $4, NULLIF($5, ''), NULLIF(RIGHT(REGEXP_REPLACE($6, '[^0-9]', '', 'g'), 10), ''), $7)
RETURNING id AS ticket_id, 'logged' AS status;
